<span class="line"><span class="__shiki_140thh">    chunk_time_interval </span><span class="__shiki_1itgoe">=&gt;</span><span class="__shiki_140thh"> INTERVAL </span><span class="__shiki_mdbnqw">&#39;7 days&#39;</span><span class="__shiki_140thh">, </span><span class="__shiki_21nrsd">-- 分块时间间隔</span></span>
